CREATE TABLE community_post (id BIGINT NOT NULL AUTO_INCREMENT,author_id BIGINT NOT NULL,game_id BIGINT NULL,title VARCHAR(160) NOT NULL,content TEXT NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'published',deleted_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),KEY idx_community_post_feed(status,created_at DESC,id DESC),KEY idx_community_post_game_feed(game_id,status,created_at DESC,id DESC),KEY idx_community_post_author(author_id,created_at DESC,id DESC),CONSTRAINT ck_community_post_status CHECK(status IN ('published','hidden','deleted')),CONSTRAINT ck_community_post_deleted CHECK((status='deleted')=(deleted_at IS NOT NULL)),CONSTRAINT ck_community_post_title CHECK(CHAR_LENGTH(TRIM(title)) BETWEEN 1 AND 160),CONSTRAINT ck_community_post_content CHECK(CHAR_LENGTH(TRIM(content)) BETWEEN 1 AND 10000),CONSTRAINT fk_community_post_author FOREIGN KEY(author_id) REFERENCES user_account(id) ON DELETE RESTRICT,CONSTRAINT fk_community_post_game FOREIGN KEY(game_id) REFERENCES game(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
